new_operation:=CASE WHEN TG_OP='DELETE' THEN NULL WHEN TG_TABLE_NAME='membership_access_operations' THEN (to_jsonb(NEW)->>'id')::uuid ELSE (to_jsonb(NEW)->>'operation_id')::uuid END;
IF old_operation IS NOT NULL AND NOT operation_shape_valid(old_operation) THEN RAISE EXCEPTION 'operation evidence and typed steps do not exactly match'; END IF;
IF new_operation IS NOT NULL AND new_operation IS DISTINCT FROM old_operation AND NOT operation_shape_valid(new_operation) THEN RAISE EXCEPTION 'operation evidence and typed steps do not exactly match'; END IF; RETURN NULL; END

DECLARE o membership_access_operations%ROWTYPE; blocked_prereq boolean; blocked_work boolean; all_done boolean; local_ok boolean; now_at timestamptz; BEGIN
 SELECT * INTO o FROM membership_access_operations WHERE id=p_operation FOR UPDATE; IF NOT FOUND OR o.state='completed' THEN RETURN; END IF;
 now_at:=clock_timestamp();
 SELECT EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND step_kind LIKE '%_prerequisite' AND state='blocked'),EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND step_kind NOT LIKE '%_prerequisite' AND state='blocked'),NOT EXISTS(SELECT 1 FROM membership_access_steps WHERE operation_id=o.id AND state<>'succeeded'),EXISTS(SELECT 1 FROM membership_access_states s WHERE s.mapping_id=o.mapping_id AND s.barrier_state='suspended' AND s.current_operation_id=o.id AND s.revision=o.transition_revision) AND o.local_enforced_at IS NOT NULL AND EXISTS(SELECT 1 FROM security_audit_events a WHERE a.operation_id=o.id AND a.mapping_id=o.mapping_id AND a.event_type='membership_access_local_enforced' AND a.outcome='success' AND a.occurred_at=o.local_enforced_at AND a.source_id IS NOT NULL) INTO blocked_prereq,blocked_work,all_done,local_ok;
 IF all_done AND local_ok THEN
  UPDATE membership_access_operations SET state='completed',completed_at=now_at,blocked_code=NULL WHERE id=o.id AND state<>'completed';
  INSERT INTO security_audit_events(id,event_type,mapping_id,outcome,reason,occurred_at,operation_id) SELECT gen_random_uuid(),'membership_access_operation_terminal',o.mapping_id,'success','completed',now_at,o.id WHERE NOT EXISTS(SELECT 1 FROM security_audit_events WHERE operation_id=o.id AND event_type='membership_access_operation_terminal');
 ELSIF blocked_prereq THEN UPDATE membership_access_operations SET state='blocked',completed_at=NULL,blocked_code='missing_external_prerequisites' WHERE id=o.id;
 ELSIF blocked_work THEN UPDATE membership_access_operations SET state='blocked',completed_at=NULL,blocked_code='external_step_blocked' WHERE id=o.id;
 ELSE UPDATE membership_access_operations SET state='reconciling',completed_at=NULL,blocked_code=NULL WHERE id=o.id; END IF;
END

